    @staticmethod
    def decrypt(s):
        key = 25
        c = bytearray(str(s).encode('utf8'))
        n = len(c)
        if (n % 2 != 0):
            return ''
        else:
            n = (n // 2)
            b = bytearray(n)
            j = 0
            for i in range(0, n):
                c1 = c[j]
                c2 = c[j + 1]
                j = (j + 2)
                c1 = (c1 - 65)
                c2 = (c2 - 65)
                b2 = (c2 * 16 + c1)
                b1 = (b2 ^ key)
                b[i] = b1
            else:
                return b.decode('utf8', 'ignore')
    @staticmethod
    def change_date_type(date):
        date_tmp = str(date)
        date = f'{date_tmp[:4]!s}-{date_tmp[4:6]!s}-{date_tmp[-2:]!s}'
        return date
    @staticmethod
    def convert_to_list(item):
        if (item == '' or item == []):
            return ({'error_no': -1, 'error_info': '查询数据报错，错误原因：fields输入格式有误'}, [])
        elif (item and not (isinstance(item, str) or isinstance(item, list))):
            return ({'error_no': -1, 'error_info': '查询数据报错，错误原因：fields输入格式有误'}, [])
        elif isinstance(item, str):
            item = item.strip().split(',')
            return ({'error_no': 0, 'error_info': ''}, item)
        else:
            return ({'error_no': 0, 'error_info': ''}, item)
    @staticmethod
    def get_year_params(start_year, end_year, report_types):
        if (report_types == '1'):
            start_year = (start_year + '-01-01')
            end_year = (end_year + '-03-31')
        elif (report_types == '2'):
            start_year = (start_year + '-04-01')
            end_year = (end_year + '-06-30')
        elif (report_types == '3'):
            start_year = (start_year + '-07-01')
            end_year = (end_year + '-09-30')
        elif (report_types == '4'):
            start_year = (start_year + '-10-01')
            end_year = (end_year + '-12-31')
        else:
            start_year = (start_year + '-01-01')
            end_year = (end_year + '-12-31')
        return (start_year, end_year)
    @staticmethod
    def date_to_quarter(date, report_types):
        year = int(date[:4])
        quarter = pandas.Period(date, 'Q-DEC').quarter
        if (report_types is None):
            if (quarter == 1):
                quarter = 4
                year -= 1
            else:
                quarter -= 1
        elif (quarter <= report_types):
            quarter = report_types
            year -= 1
        else:
            quarter = report_types
        return (str(year), str(year), str(quarter))
    def get_open_api_data(self, security, table, date=None, start_year=None, end_year=None, report_types=None, fields=None, date_type=None, merge_type=None):
        security = [security.split('.')[0] for security in eval(security)]
        if (fields is not None):
            fields = eval(fields)
        if (table in const.FINANCIAL_STATEMENTS):
            if (merge_type is None):
                merge_type = 2
            else:
                merge_type = 1
        if (not security):
            api_data = pandas.DataFrame(columns=fields)
            system_log.info('输入股票代码为空！')
            error_no = 0
            error_message = ''
            return ({'error_no': error_no, 'error_info': error_message}, api_data)
        else:
            try:
                connect = cx_Oracle.connect(f'{self._username!s}/{self._password!s}@{self._server!s}')
                cursor = connect.cursor()
                if (table == 'valuation'):
                    (sql_code, fields_list) = self.valuation_sql_get(security, fields, date)
                elif (table in const.FINANCIAL_STATEMENTS):
                    (sql_code, fields_list) = self.financial_statements_sql_get(security, table, start_year, end_year, fields, report_types, merge_type)
                elif (table in const.GROWTH_FACTORS):
                    (sql_code, fields_list) = self.growth_factors_sql_get(security, table, start_year, end_year, fields, report_types)
                else:
                    sql_code = ''
                    fields_list = []
                error_no = '0'
                error_message = ''
                cursor.execute(sql_code)
                result = cursor.fetchall()
                api_data = pandas.DataFrame(result, columns=fields_list, dtype=object)
                cursor.close()
                connect.close()
            except BaseException:
                import traceback
                from io import StringIO
                error_no = '-1'
                error_message = StringIO()
                traceback.print_exc(file=error_message)
                error_message = str(error_message.getvalue())
                system_log.error('查询数据报错，错误信息：%s' % error_message)
                api_data = EMPTY_DF
            return ({'error_no': error_no, 'error_info': error_message}, api_data)
